export type featureFlagRequestListsLogicType = MakeLogicType<
    featureFlagRequestListsLogicValues,
    featureFlagRequestListsLogicActions,
    Record<string, any>,
    featureFlagRequestListsLogicMeta
>

export const featureFlagRequestListsLogic = kea<featureFlagRequestListsLogicType>([
    path(['products', 'feature_flags', 'frontend', 'featureFlagRequestListsLogic']),
    connect(() => ({
        values: [teamLogic, ['currentTeam', 'currentTeamLoading']],
        actions: [teamLogic, ['updateCurrentTeam']],
    })),
    actions({
        setBlockedHosts: (blockedHosts: string[]) => ({ blockedHosts }),
        setBlockedIps: (blockedIps: string[]) => ({ blockedIps }),
        setAllowedHosts: (allowedHosts: string[]) => ({ allowedHosts }),
        setAllowedIps: (allowedIps: string[]) => ({ allowedIps }),
    }),
    selectors({
        blockedHosts: [
            (s) => [s.currentTeam],
            (currentTeam: TeamPublicType | TeamType | null): string[] =>
                currentTeam?.feature_flag_policy_config?.blocked_hosts ?? [],
        ],
        blockedIps: [
            (s) => [s.currentTeam],
            (currentTeam: TeamPublicType | TeamType | null): string[] =>
                currentTeam?.feature_flag_policy_config?.blocked_ips ?? [],
        ],
        allowedHosts: [
            (s) => [s.currentTeam],
            (currentTeam: TeamPublicType | TeamType | null): string[] =>
                currentTeam?.feature_flag_policy_config?.allowed_hosts ?? [],
        ],
        allowedIps: [
            (s) => [s.currentTeam],
            (currentTeam: TeamPublicType | TeamType | null): string[] =>
                currentTeam?.feature_flag_policy_config?.allowed_ips ?? [],
        ],
    }),
    listeners(({ actions }) => ({
        // Send only the edited list. The API keeps a list the request leaves out, so a save
        // here does not overwrite a newer change to the other list with the value this page loaded.
        setBlockedHosts: ({ blockedHosts }) => {
            actions.updateCurrentTeam({ feature_flag_policy_config: { blocked_hosts: blockedHosts } })
        },
        setBlockedIps: ({ blockedIps }) => {
            actions.updateCurrentTeam({ feature_flag_policy_config: { blocked_ips: blockedIps } })
        },
        setAllowedHosts: ({ allowedHosts }) => {
            actions.updateCurrentTeam({ feature_flag_policy_config: { allowed_hosts: allowedHosts } })
        },
        setAllowedIps: ({ allowedIps }) => {
            actions.updateCurrentTeam({ feature_flag_policy_config: { allowed_ips: allowedIps } })
        },
    })),
])
